#!/bin/sh
# agent002: events job (every 2m, monitor-gated) + work job (every 2h). Run inside the a9n9-agent002 container.
set -e
hermes cron edit b81245b7d76d --name events --schedule "every 2m" --add-skill a9n9-parallel --prompt "Something NEW happened: the MONITOR CHANGE block lists it (only new lines wake you). Handle every new line now:
- mail <id>: beatthechefs-mail skill (/agent/bin/mail list, read, then reply or done).
- board-ask / board-reply <id>: /agent/bin/board catchup, then answer each (board reply <id>, or react on-it and do it, or say why not).
- reminder <id> <what>: a promise you made to yourself. Do it now, then /agent/bin/remind done <id> '<what happened>'.
- newcomers <n>: a new first-time player arrived. /agent/bin/game stats: which tag or heard answer moved? Write what brought them in strategy.md; if it came from something you did, plan more of it.
- heard <n>: a new answer to the end-screen question. Read the heard object in game stats and record which option rose.
- monitor <id> <n>: /agent/bin/parallel events <id>. If a finding is a person asking for a game like ours, add it to your list of threads for Arun's review queue (with the link and a draft reply).
Lines you have already handled need nothing. Every follow-up you promise gets a reminder (/agent/bin/remind add <when> '<what>'). Write one journal line per item (/agent/bin/journal add). Finish with /agent/bin/board post '<what you handled>' --memory '<what changed, or nothing>'."
hermes cron edit 95b103a5c280 --schedule "every 120m" --prompt "Work run (every 2 hours; between runs the events job wakes you within 2 minutes for mail, board, reminders, new players, survey answers and monitor hits). Team board first (a9n9-board skill): run /agent/bin/board catchup; answer or take on any ask for you, and for each teammate post that changes what you do, change your strategy or journal and record it with /agent/bin/board react <id> learned --note '<what you changed>'. Then read /opt/data/workspace/OPERATOR.md (while its status is OPEN it comes before everything else), your journal (/agent/bin/journal), your strategy (/opt/data/workspace/strategy.md) and what people wrote to you: email first (/agent/bin/mail list; answer or close every message with the beatthechefs-mail skill), then Bluesky (/agent/bin/bsky-read notifications). Then finish at least ONE action toward your goal that a person outside the team will see or that produces something Arun can post. Use /agent/bin/parallel (skill a9n9-parallel) to find people who are asking for a game like ours: findall for recent threads, monitor for new ones. Catalogue listing stays stopped. A run that only re-reads numbers is a failed run. Every follow-up gets a reminder: /agent/bin/remind add <+2h|+2d|2026-11-25T09:00Z> '<what>'. Then update the strategy with what you learned and write what you did, learned and plan next with /agent/bin/journal add. Last step, every run: /agent/bin/board post '<what you did and what happened, with numbers>' --memory '<what you changed in strategy.md, journal or skills, or nothing>' --learned <ids of teammate posts you used, if any>."
hermes cron list 2>&1 | grep -E "Name:|Schedule:|Skills:"
